document.addEventListener('input',event=>{if(modal&&modalRoot.contains(event.target)&&event.target.closest('form'))modalDirty=true;});
document.addEventListener('change', async event => {
  if(modal&&modalRoot.contains(event.target)&&event.target.closest('form'))modalDirty=true;
  if(event.target.id==='plan-billing'){const price=document.getElementById('plan-price');const free=event.target.value==='free';price.disabled=free;price.min=free?'0':'0.01';if(free)price.value='0';return;}
  if(event.target.id==='plan-default'&&event.target.checked){document.getElementById('plan-active').checked=true;return;}
  if(event.target.id==='application-status'){applicationStatusFilter=event.target.value;render();return;}
  if(event.target.id==='need-status'){needStatusFilter=event.target.value;render();return;}
  if(event.target.id==='message-template'){const template=messageTemplates[event.target.value];if(template){document.getElementById('message-subject').value=template.subject;document.getElementById('message-body').value=template.body;}return;}
  if(event.target.id==='message-channel' || event.target.id==='message-cohort'){
    const channel=document.getElementById('message-channel').value;
    const cohort=document.getElementById('message-cohort').value;
    const subject=document.getElementById('message-subject');subject.required=channel==='email';subject.disabled=channel!=='email';
    document.getElementById('message-body').maxLength=channel==='sms'?1500:5000;
    document.getElementById('message-body-help').textContent=`Up to ${channel==='sms'?'1,500':'5,000'} characters. Replace bracketed placeholders. Every selected recipient receives this same text.`;
    modalRoot.querySelectorAll('.recipient-row').forEach(row=>{const checkbox=row.querySelector('input');const user=(data.users || []).find(u=>u.id===checkbox.value);const eligible=user && eligibleForChannel(user,channel);row.hidden=cohort!=='all' && user?.cohort!==cohort;checkbox.disabled=!eligible;if(!eligible || row.hidden)checkbox.checked=false;row.querySelector('.recipient-detail').textContent=eligible?(channel==='email'?user.email:user.phone):'Contact detail and recorded permission required';const badge=row.querySelector('.badge');badge.textContent=eligible?'Eligible':'Unavailable';badge.className=`badge ${eligible?'green':'outline'}`;});return;
  }
  if (!event.target.dataset.filter) return;
  if (event.target.dataset.filter==='cohort') filterCohort=event.target.value;
  if (event.target.dataset.filter==='stage') filterStage=event.target.value;
  try { await loadMetrics(); render(); } catch(error) { notify(error.message,true); }
});
document.addEventListener('keydown', event => {
  if(!modal&&navigationOpen){if(event.key==='Escape'){event.preventDefault();setNavigation(false);}if(event.key==='Tab'){const nodes=Array.from(document.querySelectorAll('#primary-navigation button:not(:disabled)'));const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}return;}
  if (!modal) return;
  if (event.key==='Escape'){event.preventDefault();requestCloseModal();}
  if (event.key==='Tab') { const nodes=Array.from(modalRoot.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')); const first=nodes[0], last=nodes[nodes.length-1]; if (event.shiftKey && document.activeElement===first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement===last) { event.preventDefault(); first?.focus(); } }
});
