    if(type==='ai-settings'){const result=await api('/api/admin/ai-settings','PUT',{model:values.model.trim(),...(values.apiKey?.trim()?{apiKey:values.apiKey.trim()}:{})});form.reset();values.apiKey='';formData.delete('apiKey');data.aiSettings=result.aiSettings;render();notify('AI settings saved.');try{await refreshState();render();}catch{notify('AI settings saved. Refresh to load the current connection status.',true);}return;}
    if(type==='need'){await api('/api/needs','POST',{category:values.category,summary:values.summary,priority:values.priority});await refreshState();closeModal();await navigate('support');notify('Your support request is saved.');return;}
