window.addEventListener('resize',syncNavigation);
window.addEventListener('hashchange',()=>{if(data.user)void navigateFromHash();});

(async function boot() {
  try { await refreshState(); if(data.user)await navigateFromHash();else render(); }
  catch(error) { app.innerHTML=`<main id="main" class="initial-loading"><div class="panel" style="max-width:480px">${brand()}<h2 class="mt-24">We couldn’t open the workspace.</h2><p class="small muted mt-16">${esc(error.message)}</p><button class="btn btn-primary mt-24" data-action="reload">Try again </button></div></main>`; }
})();
